        // Render stats cards
        function renderStats(data) {
            const totalDue = data.reduce((sum, d) => sum + parseInt(d.children_due), 0);
            const totalImmunised = data.reduce((sum, d) => sum + parseInt(d.children_fully_immunised), 0);
            const overallRate = ((totalImmunised / totalDue) * 100).toFixed(1);
            const bestDistrict = data.reduce((best, current) => {
                const bestRate = parseInt(best.children_fully_immunised) / parseInt(best.children_due);
                const currentRate = parseInt(current.children_fully_immunised) / parseInt(current.children_due);
                return currentRate > bestRate ? current : best;
            });

            document.getElementById('statsGrid').innerHTML = `
                <div class="stat-card">
                    <h3>Total Children Due</h3>
                    <div class="value">${totalDue.toLocaleString()}</div>
                </div>
                <div class="stat-card">
                    <h3>Total Fully Immunised</h3>
                    <div class="value">${totalImmunised.toLocaleString()}</div>
                </div>
                <div class="stat-card">
                    <h3>Overall Immunisation Rate</h3>
                    <div class="value">${overallRate}%</div>
                </div>
                <div class="stat-card">
                    <h3>Best Performing District</h3>
                    <div class="value">${bestDistrict.district}</div>
                </div>
            `;
        }

        // Render data table
        function renderTable(data) {
            const tbody = document.querySelector('#dataTable tbody');
            tbody.innerHTML = data.map(item => {
                const percentage = ((parseInt(item.children_fully_immunised) / parseInt(item.children_due)) * 100).toFixed(1);
                return `
                    <tr>
                        <td><strong>${item.district}</strong></td>
                        <td>${parseInt(item.children_due).toLocaleString()}</td>
                        <td>${parseInt(item.children_fully_immunised).toLocaleString()}</td>
                        <td class="percentage">${percentage}%</td>
                    </tr>
                `;
            }).join('');
        }

        // Update source
        function updateSource(data) {
            const source = data[0]?.source || 'Unknown';
            document.getElementById('dataSource').textContent = source;
        }

        // Main update function
        function updateDashboard(year) {
            selectedYear = year;
            const data = getDataByYear(year);
            renderBarChart(data);
            renderStats(data);
            renderTable(data);
            updateSource(data);
        }

        // Event listener for year selection
        document.getElementById('yearSelect').addEventListener('change', (e) => {
            updateDashboard(e.target.value);
        });

        // Initialize dashboard
        updateDashboard(selectedYear);
    </script>
</body>
</html>
