const allData = parseCSV(csvData);
let selectedYear = '2023';

// Filter data by year
function getDataByYear(year) {
    return allData.filter(d => d.year === year);
}

// Find lowest performing district
function findLowestDistrict(data) {
    return data.reduce((lowest, current) => {
        const lowestRate = parseInt(lowest.children_fully_immunised) / parseInt(lowest.children_due);
        const currentRate = parseInt(current.children_fully_immunised) / parseInt(current.children_due);
        return currentRate < lowestRate ? current : lowest;
    });
}

// Render bar chart
function renderBarChart(data, lowestDistrict) {
    const container = document.getElementById('barChart');
    const maxVal = Math.max(...data.map(d => parseInt(d.children_fully_immunised)));

    container.innerHTML = data.map(item => {
        const percentage = ((parseInt(item.children_fully_immunised) / parseInt(item.children_due)) * 100).toFixed(1);
        const width = (parseInt(item.children_fully_immunised) / maxVal) * 100;
        const isLowest = item.district === lowestDistrict.district;
        const lowestClass = isLowest ? 'lowest' : '';

        return `
            <div class="bar-row">
                <div class="district-label ${lowestClass}">${item.district}${isLowest ? ' ⚠️' : ''}</div>
                <div class="bar-wrapper">
                    <div class="bar-bg">
                        <div class="bar-fill ${lowestClass}" style="width: ${width}%">${item.children_fully_immunised}</div>
                    </div>
                    <div class="bar-value">${percentage}% rate</div>
                </div>
            </div>
        `;
    }).join('');
}

